<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/classes/IdiomaService.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['autenticado']) || empty($_SESSION['tenant']['banco_dados'])) { http_response_code(401); exit(IdiomaService::t('home.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__) . '/classes/UsuarioSessao.php';
require_once dirname(__DIR__) . '/classes/TaskService.php';
require_once dirname(__DIR__) . '/classes/AgendaService.php';
$pdo = GreenPortalDatabase::connect(GreenPortalDatabase::env(), (string)$_SESSION['tenant']['banco_dados'], 'GPT');
if (!UsuarioSessao::atualizar($pdo, $_SESSION)) { http_response_code(401); exit(IdiomaService::t('home.erro.sessao', ['pt' => 'Sessão expirada.', 'en' => 'Your session has expired.', 'es' => 'Su sesión expiró.'])); }
$userId = (int)($_SESSION['usuario']['codusuario'] ?? 0);
$e = static fn(mixed $value): string => htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
$actions = [];
try {
    $agenda = new AgendaService($pdo, new TaskService($pdo));
    $events = $agenda->listForUser($userId, date('Y-m-d 00:00:00'), date('Y-m-d 00:00:00', strtotime('+90 days')));
    foreach ($events as $event) $actions[] = ['date' => $event['inicio'] ?? '', 'type' => IdiomaService::t('home.tipo.agenda', ['pt' => 'Agenda', 'en' => 'Agenda', 'es' => 'Agenda']), 'title' => $event['titulo'] ?? '', 'status' => $event['status'] ?? '', 'description' => $event['descricao'] ?? ''];
} catch (Throwable) { $events = []; }
try {
    $stmt = $pdo->prepare("SELECT titulo,descricao,data_limite,status,'TAREFA' AS tipo FROM green_tasks WHERE codusuario_destino=:usuario AND status IN ('PENDENTE','PROCESSANDO') ORDER BY data_limite IS NULL,data_limite LIMIT 300");
    $stmt->execute(['usuario' => $userId]);
    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $task) $actions[] = ['date' => $task['data_limite'] ?? '', 'type' => IdiomaService::t('home.tipo.tarefa', ['pt' => 'Tarefa', 'en' => 'Task', 'es' => 'Tarea']), 'title' => $task['titulo'] ?? '', 'status' => $task['status'] ?? '', 'description' => $task['descricao'] ?? ''];
} catch (Throwable) {}
usort($actions, static fn(array $a, array $b): int => strcmp((string)$a['date'], (string)$b['date']));
?>
<!doctype html><html lang="<?= IdiomaService::idioma() === 'pt' ? 'pt-BR' : IdiomaService::idioma() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link href="../assets/vendor/bootstrap/css/bootstrap.min.css?v=2" rel="stylesheet"><link href="../assets/vendor/bootstrap-icons/font/bootstrap-icons.min.css?v=2" rel="stylesheet"><style>body{margin:0;background:#fff;color:var(--gp-text);font:13px Arial,sans-serif}.frame{padding:16px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.head h2{font-size:18px;margin:0}.head small{color:var(--gp-muted)}.table-wrap{overflow:auto;border:1px solid var(--gp-border);border-radius:8px}.table{margin:0;font-size:12px}.table th{background:var(--gp-primary-soft);color:var(--gp-muted);font-weight:600;white-space:nowrap}.table td,.table th{padding:9px 10px;vertical-align:middle}.muted{color:var(--gp-muted)}.empty{padding:35px;text-align:center;color:var(--gp-muted)}</style><?php require_once dirname(__DIR__) . '/components/pagina_padrao.php'; greenPortalEstiloPagina(); ?></head><body><main class="frame"><header class="head"><div><h2><i class="bi bi-calendar2-week me-2"></i><?= htmlspecialchars(IdiomaService::t('home.agenda.titulo', ['pt' => 'Minhas ações', 'en' => 'My actions', 'es' => 'Mis acciones']), ENT_QUOTES, 'UTF-8') ?></h2><small><?= htmlspecialchars(IdiomaService::t('home.agenda.subtitulo', ['pt' => 'Agenda e tarefas atribuídas ao usuário autenticado.', 'en' => 'Agenda and tasks assigned to the signed-in user.', 'es' => 'Agenda y tareas asignadas al usuario autenticado.']), ENT_QUOTES, 'UTF-8') ?></small></div><span class="badge text-bg-light"><?= count($actions) ?> <?= htmlspecialchars(IdiomaService::t('home.itens', ['pt' => 'item(ns)', 'en' => 'item(s)', 'es' => 'ítem(s)']), ENT_QUOTES, 'UTF-8') ?></span></header><?php if (!$actions): ?><div class="empty"><i class="bi bi-calendar-check fs-3 d-block mb-2"></i><?= htmlspecialchars(IdiomaService::t('home.agenda.vazio', ['pt' => 'Nenhuma ação pendente ou programada.', 'en' => 'No pending or scheduled actions.', 'es' => 'No hay acciones pendientes o programadas.']), ENT_QUOTES, 'UTF-8') ?></div><?php else: ?><div class="table-wrap"><table class="table table-hover"><thead><tr><th><?= htmlspecialchars(IdiomaService::t('home.coluna.data', ['pt' => 'Data', 'en' => 'Date', 'es' => 'Fecha']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('home.coluna.tipo', ['pt' => 'Tipo', 'en' => 'Type', 'es' => 'Tipo']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('home.coluna.acao', ['pt' => 'Ação', 'en' => 'Action', 'es' => 'Acción']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('home.coluna.descricao', ['pt' => 'Descrição', 'en' => 'Description', 'es' => 'Descripción']), ENT_QUOTES, 'UTF-8') ?></th><th><?= htmlspecialchars(IdiomaService::t('home.coluna.status', ['pt' => 'Status', 'en' => 'Status', 'es' => 'Estado']), ENT_QUOTES, 'UTF-8') ?></th></tr></thead><tbody><?php foreach($actions as $item): ?><tr><td><?= $e($item['date']) ?></td><td><?= $e($item['type']) ?></td><td><?= $e($item['title']) ?></td><td><?= $e($item['description']) ?></td><td><?= $e($item['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></main></body></html>
